        a5: "การทดลองใช้อยู่ในแพ็กเกจ POS สำหรับการสมัครครั้งแรกของบัญชี และไม่ต้องใช้บัตร หากต้องการใช้ POS ต่อหลังครบ 14 วัน ให้เพิ่มบัตรในการเรียกเก็บเงิน ระบบจะเรียกเก็บครั้งแรกเมื่อสิ้นสุดการทดลอง หากไม่มีบัตร บัญชีของคุณจะกลับไปที่แพ็กเกจ Free และเมนู ออเดอร์ และพนักงานของคุณยังอยู่ครบ",
        q6: "Epidom ได้รับการรับรอง NF525 หรือไม่",
