        q7: "Epidom ราคาเท่าไร",
        a7: "เริ่มใช้ฟรี หน้าเมนูและ QR code ใช้ฟรีตลอดไป POS เดือนละ {pos} (เดือนละ {posYear} เมื่อชำระรายปี) และ Operations {ops} ({opsYear}) ยังไม่รวมภาษี Operations รองรับได้สูงสุด 3 สาขา ส่วนเครือข่ายตั้งแต่ 4 สาขาขึ้นไปใช้ Enterprise ซึ่งกำหนดราคาร่วมกับคุณ POS ใช้ฟรี 14 วัน ไม่ต้องใช้บัตร",
        q8: "นำเมนูจากเครื่องคิดเงินเดิมมาใช้ได้ไหม",
