        q10: "ถาม Claude เรื่องตัวเลขของฉันได้ไหม",
        a10: "ได้ ตั้งแต่แพ็กเกจ Operations (Beta) เชื่อมต่อ Epidom กับ Claude แล้วถามด้วยภาษาง่าย ๆ เช่น ยอดขายเมื่อวาน อะไรใกล้หมด กำไรสัปดาห์นี้ ใครอยู่ในตารางงาน Claude อ่านข้อมูลของคุณได้ ส่วนบน Enterprise ยังแก้ไขข้อมูลได้ด้วย โดยต้องได้รับการอนุมัติจากคุณทุกครั้ง",
