      item1:
        "ผู้ช่วย AI ที่คุณเชื่อมต่อ: หากคุณเชื่อมต่อ Epidom กับผู้ช่วย AI ของคุณเอง (ตัวเชื่อมต่อ Claude แพ็กเกจ Operations ขึ้นไป) ข้อมูลที่คุณหรือผู้ช่วยร้องขอจะถูกส่งไปยังผู้ช่วยนั้นตามคำขอของคุณ ภายใต้บัญชีของคุณกับผู้ให้บริการรายนั้น (Anthropic สำหรับ Claude) และนโยบายความเป็นส่วนตัวของผู้ให้บริการ ผู้ช่วยเข้าถึงได้เฉพาะสิ่งที่สิทธิ์เข้าถึง Epidom ของคุณอนุญาต คุณเป็นผู้เลือกว่าจะให้ทำการเปลี่ยนแปลงได้หรือไม่ และคุณเพิกถอนได้ทุกเมื่อจากโปรไฟล์ Epidom ของคุณ Epidom เก็บบันทึกว่ามีการใช้เครื่องมือใดและการเปลี่ยนแปลงทุกรายการที่เกิดขึ้น โดยไม่เก็บเนื้อหาการสนทนาของคุณ",
